"/**
 * Auth group layout — wraps /(auth)/login and /(auth)/verify-otp.
 *
 * Uses a Stack navigator with no visible header so each auth screen can
 * define its own full-screen UI without interference from navigation chrome.
 */

import { Stack } from 'expo-router';

export default function AuthLayout() {
  return (
    <Stack screenOptions={{ headerShown: false }}>
      <Stack.Screen name="login" />
      <Stack.Screen name="verify-otp" />
    </Stack>
  );
}
"

"/**
 * Protected app group layout.
 *
 * Acts as the second line of defence against unauthenticated access:
 * if the root layout redirect hasn't fired yet (edge case on slow devices),
 * this layout also redirects to login.
 *
 * Contains a Stack that hosts:
 *  • (tabs)  — the three main tabs
 *  • profile — the profile screen (pushed modally from any tab)
 */

import { Redirect, Stack } from 'expo-router';

import { useAuthStore } from '@/store/auth-store';

export default function AppLayout() {
  const { isAuthenticated, isHydrated } = useAuthStore();

  // Still loading from SecureStore — render nothing to avoid a flash.
  if (!isHydrated) return null;

  // Belt-and-suspenders redirect (the root layout does this too).
  if (!isAuthenticated) {
    return <Redirect href="/(auth)/login" />;
  }

  return (
    <Stack screenOptions={{ headerShown: false }}>
      {/* Transparent group: (tabs) renders the tab bar */}
      <Stack.Screen name="(tabs)" />
      {/* Profile is pushed as a card over the tabs */}
      <Stack.Screen
        name="profile"
        options={{
          headerShown: true,
          title: 'Profile',
          presentation: 'card',
        }}
      />
    </Stack>
  );
}
"

"/**
 * Tab navigator layout for the three main app tabs.
 *
 * Tab visibility can be made role-aware here — e.g. hide the
 * Referrals tab for patients — by reading from the auth store.
 */

import { Tabs } from 'expo-router';
import { useColorScheme } from 'react-native';

import { Colors } from '@/constants/theme';
import { useAuthStore } from '@/store/auth-store';

export default function TabsLayout() {
  const colorScheme = useColorScheme() ?? 'light';
  const colors = Colors[colorScheme === 'dark' ? 'dark' : 'light'];
  const role = useAuthStore((s) => s.user?.role);

  return (
    <Tabs
      screenOptions={{
        headerShown: false,
        tabBarActiveTintColor: '#3C9FFE',
        tabBarInactiveTintColor: colors.textSecondary,
        tabBarStyle: { backgroundColor: colors.background },
      }}
    >
      {/* ── Home / Dashboard ── */}
      <Tabs.Screen
        name="index"
        options={{
          title: 'Home',
          tabBarIcon: ({ color, size }) => (
            // SymbolView not available here without native view context;
            // replace with expo-symbols <SymbolView> once screens are built.
            null
          ),
        }}
      />

      {/* ── Referrals (agents + patients) ── */}
      <Tabs.Screen
        name="referrals"
        options={{
          title: 'Referrals',
          // Agents see their referral pipeline; patients see their own status.
        }}
      />

      {/* ── Wallet / Points ── */}
      <Tabs.Screen
        name="wallet"
        options={{
          title: role === 'agent' ? 'Earnings' : 'Wallet',
        }}
      />
    </Tabs>
  );
}
"

